import { db } from "../src/db/connection";
import { existsSync } from "node:fs";

describe("Database Initialization", () => {
  beforeAll(() => {
    // The database should already be initialized because of the auto-call in connection.ts
  });

  test("Database file exists", () => {
    expect(existsSync("data/moment-diary.db")).toBe(true);
  });

  test("Required tables exist", () => {
    const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all() as { name: string }[];
    const tableNames = tables.map(t => t.name);

    expect(tableNames).toContain("users");
    expect(tableNames).toContain("sessions");
    expect(tableNames).toContain("diary_entries");
    expect(tableNames).toContain("tags");
    expect(tableNames).toContain("diary_tags");
  });

  test("Database schema for users table is correct", () => {
    const info = db.prepare("PRAGMA table_info(users)").all() as { name: string; type: string }[];
    const columns = info.map(c => c.name);

    expect(columns).toContain("id");
    expect(columns).toContain("username");
    expect(columns).toContain("password_hash");
    expect(columns).toContain("created_at");
  });

  test("Foreign keys are enabled", () => {
    const result = db.prepare("PRAGMA foreign_keys").get() as { foreign_keys: number };
    expect(result.foreign_keys).toBe(1);
  });
});
