{"content":"import { db } from "../db/connection";
import { randomBytes } from "node:crypto";

export interface User {
  id: number;
  email: string;
  password_hash: string;
  created_at: string;
}

export interface Session {
  id: number;
  user_id: number;
  token: string;
  expires_at: string;
}

export class AuthService {
  static async register(email: string, password: string): Promise<User> {
    const passwordHash = await Bun.password.hash(password);
    const result = db.prepare(
      "INSERT INTO users (email, password_hash) VALUES (?, ?) RETURNING *"
    ).get(email, passwordHash) as User;
    return result;
  }

  static async login(email: string, password: string): Promise<string | null> {
    const user = db.prepare("SELECT * FROM users WHERE email = ?").get(email) as User | undefined;

    if (!user) return null;

    const isPasswordValid = await Bun.password.verify(password, user.password_hash);
    if (!isPasswordValid) return null;

    const token = randomBytes(32).toString("hex");
    // Session expires in 7 days
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

    db.prepare(
      "INSERT INTO sessions (user_id, token, expires_at) VALUES (?, ?, ?)"
    ).run(user.id, token, expiresAt);

    return token;
  }

  static getUserByToken(token: string): User | null {
    const session = db.prepare(
      "SELECT u.* FROM users u JOIN sessions s ON u.id = s.user_id WHERE s.token = ? AND s.expires_at > ?"
    ).get(token, new Date().toISOString()) as User | undefined;

    return session || null;
  }
}
