  title: string | null;
  content: string;
  mood: string | null;
  is_favorite: number;
  created_at: string;
  updated_at: string;
  tags?: string[];
}

export class DiaryService {
  static create(userId: number, data: { title?: string; content: string; mood?: string; is_favorite?: boolean; tags?: string[] }): DiaryEntry {
    const { title, content, mood, is_favorite = false, tags = [] } = data;
    const isFavoriteInt = is_favorite ? 1 : 0;

    const transaction = db.transaction(() => {
      // 1. Insert diary entry
      const result = db.prepare(`
        INSERT INTO diary_entries (user_id, title, content, mood, is_favorite)
        VALUES (?, ?, ?, ?, ?)
        RETURNING *
      `).get(userId, title || null, content, mood || null, isFavoriteInt) as any;

      const diaryId = result.id;

      // 2. Handle tags
      for (const tagName of tags) {
        const normalized = tagName.trim().toLowerCase();
        if (!normalized) continue;

        // Ensure tag exists for this user
        db.run(`
          INSERT OR IGNORE INTO tags (user_id, name, normalized_name)
          VALUES (?, ?, ?)
        `, [userId, tagName.trim(), normalized]);

        const tag = db.prepare(`
          SELECT id FROM tags WHERE user_id = ? AND normalized_name = ?
