{"command":"cat <<EOF > src/diary/timeline.test.ts
import { expect, test, describe, beforeAll } from "bun:test";
import { db } from "../db/connection";
import { AuthService } from "../auth/service";
import { DiaryService } from "./service";
import { existsSync } from "node:fs";

describe("Timeline Sorting", () => {
  let userId: number;

  beforeAll(async () => {
    // Clean database
    if (existsSync("data/moment-diary.db")) {
      db.run(\`DELETE FROM diary_tags\`);
      db.run(\`DELETE FROM diary_entries\`);
      db.run(\`DELETE FROM tags\`);
      db.run(\`DELETE FROM sessions\`);
      db.run(\`DELETE FROM users\`);
    }

    const user = await AuthService.register("timeline@example.com", "password123");
    userId = user.id;

    // Create entries with specific created_at times (manual insert to control time)
    // Entry 1 (Oldest)
    db.prepare(\`
      INSERT INTO diary_entries (user_id, content, created_at)
      VALUES (?, ?, ?)
    \`).run(userId, "Oldest", "2023-01-01 10:00:00");

    // Entry 2 (Middle)
    db.prepare(\`
      INSERT INTO diary_entries (user_id, content, created_at)
      VALUES (?, ?, ?)
    \`).run(userId, "Middle", "2023-01-02 10:00:00");

    // Entry 3 (Newest)
    db.prepare(\`
      INSERT INTO diary_entries (user_id, content, created_at)
      VALUES (?, ?, ?)
    \`).run(userId, "Newest", "2023-01-03 10:00:00");
  });

  test("should return entries in descending order of created_at", () => {
    const timeline = DiaryService.timeline(userId, {});
    expect(timeline.length).toBe(3);
    expect(timeline[0].content).toBe("Newest");
    expect(timeline[1].content).toBe("Middle");
    expect(timeline[2].content).toBe("Oldest");
  });
});
